    if (placement.ActivePlacement != null)
    {
        int.TryParse(placement.ActivePlacement.ToString(), out activePlacement);
    }
    if (placement.Status != "Choose Action")
    {
        activePlacement += firstNum + secondNum;


        if (gameCards.Count <= activePlacement)
        {
            GameHelpers.CloseRound(myGame, myTeam, myuser, _context);

            activePlacement = activePlacement - gameCards.Count;
            //test if the game limit has reached!
        }
        placement.FirstNum = firstNum;
        placement.LastNum = secondNum;

        placement.ActivePlacement = activePlacement;
        placement.Status = "Choose Action";
        _context.SaveChanges();
    }
