    List<Stages> stages = new List<Stages>();
    foreach (Actions actionI in actions)
    {
        var newStages = _context.Stages.Where(a => a.ParentId == actionI.Id.ToString() && a.Language == language && a.Step >= prev_step).OrderBy(a => a.Step).ThenBy(a => a.Priority).ToList();
        stages.AddRange(newStages);
    }




    for(var p=0;p< stages.Count;p++)
    {
        var stage = stages[p];
        stage.HasStages = false;

        if(myuser!=null)
        {
            var userAnswer = _context.UserAnswers.Where(a => a.ParentId == stage.Id.ToString() && a.UserId == myuser.Id.ToString()).FirstOrDefault();
            if(userAnswer!=null)
            {
                stage.UserAnswer = userAnswer.Answer;
            }
            else
            {
                stage.UserAnswer = "";
            }

            var review = _context.Reviews.Where(a => a.StageId == stage.Id.ToString() && a.UserId == myuser.Id.ToString()).FirstOrDefault();
            if (review != null)
            {
                stage.Review = review.Review;
            }
            else
            {
                stage.Review = "";
            }
        }

    }
    return stages;
}

